import{_ as s,H as i,o as d,c as n,aO as o,q as r,s as t,a as c,l as _,aU as l}from"./chunks/framework.vjUPZZJn.js";const p=JSON.parse('{"title":"AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁","description":"","frontmatter":{"date":"2026-10-29T09:56:00.000Z","title":"AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁","source":[["1-知识/机器人/ROS2/AdmittanceTransforms六个位姿"]],"tags":["机器人","源码阅读","学习笔记","ROS2","力控制"],"categories":["机器人"],"permalink":"/pages/77ee5e"},"headers":[],"relativePath":"机器人/AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁.md","filePath":"机器人/AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁.md","lastUpdated":1793240540000}'),E={name:"机器人/AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁.md"};function B(m,e,A,f,b,h){const a=i("Mermaid");return d(),n("div",null,[e[4]||(e[4]=o('<h1 id="admittancetransforms-的六个位姿-导纳定律的坐标桥梁" tabindex="-1">AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁 <a class="header-anchor" href="#admittancetransforms-的六个位姿-导纳定律的坐标桥梁" aria-label="Permalink to &quot;AdmittanceTransforms 的六个位姿：导纳定律的坐标桥梁&quot;">​</a></h1> <p>ros2_controllers（Humble，commit <code>2105376</code>）的 admittance_controller 里有个容易被一眼扫过的结构体 <code>AdmittanceTransforms</code>（<code>admittance_rule.hpp:43-61</code>）：它缓存一个控制周期需要的 6 个位姿，由 <code>get_all_transforms</code>（<code>admittance_rule_impl.hpp:142-167</code>）调 6 次 <code>kinematics_-&gt;calculate_link_transform()</code> 填满——第 1 次用参考关节角，后 5 次用当前关节角。为什么恰好是这六个、各自被谁消费？这六个位姿是理解导纳定律坐标系关系的钥匙：力在 sensor frame 测得、重力只在 world frame 是常向量、M/D/K 定义在 control frame、弹簧零点在参考轨迹上，把它们搬进 base frame 全靠这六座桥。文中行号对应锚点 commit 的源码。控制器整体架构见<a href="./ros2_control 控制器架构与 chainable 机制.html">本站《ros2_control 控制器架构与 chainable 机制》</a>。</p> <h2 id="六个位姿与消费点" tabindex="-1">六个位姿与消费点 <a class="header-anchor" href="#六个位姿与消费点" aria-label="Permalink to &quot;六个位姿与消费点&quot;">​</a></h2> <p>导纳定律在 base frame 计算：<code>X_ddot = M⁻¹(F_base − D·X_dot − K·X)</code>（impl:290-292）。定律的输入分别诞生在别的 frame，六个位姿就是搬运工：</p> <table tabindex="0"><thead><tr><th>成员</th> <th>含义</th> <th>关节角</th> <th>消费点</th> <th>用哪部分</th></tr></thead> <tbody><tr><td><code>ref_base_ft_</code></td> <td>传感器在参考构型下的位姿</td> <td><strong>参考</strong>（:147）</td> <td>:202 存入 state → :261-265 算 X 的零点</td> <td>平移+旋转</td></tr> <tr><td><code>base_ft_</code></td> <td>传感器当前位姿</td> <td>当前（:152）</td> <td>:187 组 <code>R_world_sensor</code></td> <td>仅旋转</td></tr> <tr><td><code>world_base_</code></td> <td>base 在 world 下的位姿</td> <td>当前（:156）</td> <td>:187 / :189 / :194-196 三次</td> <td>仅旋转</td></tr> <tr><td><code>base_cog_</code></td> <td>工具质心当前位姿</td> <td>当前（:159）</td> <td>:189 重力力矩杠杆臂</td> <td>仅旋转（配 <code>cog_pos_</code> 参数）</td></tr> <tr><td><code>base_control_</code></td> <td>control frame 当前位姿</td> <td>当前（:162）</td> <td>:200 → K/D 共轭旋转（:238/:252）、轴掩码往返（:282-288）</td> <td>仅旋转</td></tr> <tr><td><code>base_tip_</code></td> <td>末端当前位姿</td> <td>当前（:154）</td> <td><strong>无</strong>（:155 写入后全包零读取）</td> <td>—</td></tr></tbody></table> ',10)),(d(),r(l,null,{default:t(()=>[_(a,{id:"mermaid-137",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20q_ref%5B%22%E5%8F%82%E8%80%83%E5%85%B3%E8%8A%82%E8%A7%92%EF%BC%88%3A147%EF%BC%89%22%5D%20--%3E%20REF%5B%22ref_base_ft_%20%E5%BC%B9%E7%B0%A7%E9%9B%B6%E7%82%B9%22%5D%0A%20%20%20%20q_cur%5B%22%E5%BD%93%E5%89%8D%E5%85%B3%E8%8A%82%E8%A7%92%EF%BC%88%3A152-162%EF%BC%89%22%5D%20--%3E%20FT%5B%22base_ft_%EF%BC%88%3A152%EF%BC%89%22%5D%0A%20%20%20%20q_cur%20--%3E%20TIP%5B%22base_tip_%EF%BC%88%3A154%EF%BC%8C%E6%97%A0%E4%BA%BA%E8%AF%BB%E5%8F%96%EF%BC%89%22%5D%0A%20%20%20%20q_cur%20--%3E%20WB%5B%22world_base_%EF%BC%88%3A156%EF%BC%8C%E5%9B%BA%E5%AE%9A%E5%9F%BA%E5%BA%A7%E4%B8%8B%E4%B8%BA%E5%B8%B8%E9%87%8F%EF%BC%89%22%5D%0A%20%20%20%20q_cur%20--%3E%20COG%5B%22base_cog_%EF%BC%88%3A159%EF%BC%89%22%5D%0A%20%20%20%20q_cur%20--%3E%20CTRL%5B%22base_control_%EF%BC%88%3A162%EF%BC%89%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(`
          Loading...
        `,-1)])]),_:1})),e[5]||(e[5]=o('<h2 id="参考-vs-当前-两份关节角-两个世界" tabindex="-1">参考 vs 当前：两份关节角，两个世界 <a class="header-anchor" href="#参考-vs-当前-两份关节角-两个世界" aria-label="Permalink to &quot;参考 vs 当前：两份关节角，两个世界&quot;">​</a></h2> <ul><li>参考世界：第①拍 <code>read_state_reference_interfaces</code>（<code>admittance_controller.cpp:447</code>）读 reference interfaces。这组接口有两个写入者——级联时 JTC 直接写；独立运行时话题经 RealtimeBuffer 由 <code>update_reference_from_subscribers</code>（:402-430）写入。基类 <code>update()</code> 先调话题消费再调 <code>update_and_write_commands</code>（<code>chainable_controller_interface.cpp:35→42</code>）。</li> <li>当前世界：第②拍 <code>read_state_from_hardware</code>（:450）读 hardware state interfaces（编码器）。</li> <li>对应工业控制器的<strong>设定点 vs 编码器反馈</strong>；定律里的 X 是跟随误差的笛卡尔版本。</li> <li>六个位姿里只有 <code>ref_base_ft_</code> 住在参考世界——弹簧零点需要「上游要你去哪」。其余五个全是当前构型：力怎么旋转、重力怎么减、参数怎么换系只取决于臂的真实姿态。用参考姿态旋转力读数会在臂滞后于指令时出错，而臂滞后最大的时刻恰是接触加载、力读数最重要的时刻。</li> <li>实测关节角 ≈ 上周期指令（参考 + 累积 Δq），hpp 注释 &quot;at reference + admittance offset joint angles&quot; 说的就是这层物理含义。</li></ul> <h2 id="力的通路-为什么绕道-world" tabindex="-1">力的通路：为什么绕道 world <a class="header-anchor" href="#力的通路-为什么绕道-world" aria-label="Permalink to &quot;力的通路：为什么绕道 world&quot;">​</a></h2> <p>传感器帧 → world → base，三座桥（<code>base_ft_</code> / <code>world_base_</code> / <code>base_cog_</code>）：</p> ',8)),(d(),r(l,null,{default:t(()=>[_(a,{id:"mermaid-174",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20S%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%E5%B8%A7%EF%BC%9Awrench%20%E5%9C%A8%E8%BF%99%E9%87%8C%E6%B5%8B%E5%BE%97%22%5D%20--%3E%7C%22base_ft_%20%E4%BB%85%E6%97%8B%E8%BD%AC%22%7C%20B%5B%22base%20%E5%B8%A7%EF%BC%9A%E5%AE%9A%E5%BE%8B%E7%9A%84%E5%AE%B6%22%5D%0A%20%20%20%20B%20--%3E%7C%22world_base_%20%E4%BB%85%E6%97%8B%E8%BD%AC%22%7C%20W%5B%22world%20%E5%B8%A7%EF%BC%9A%E9%87%8D%E9%87%8F%20%3D%20%E5%B8%B8%E5%90%91%E9%87%8F%20%5B0%2C0%2C%E2%88%92w%5D%22%5D%0A%20%20%20%20W%20--%3E%20P%5B%22%E5%87%8F%E9%87%8D%E5%8A%9B%EF%BC%9A%E5%8A%9B%20%E2%88%92w%E3%80%81%E5%8A%9B%E7%9F%A9%20%E2%88%92r%C3%97w%EF%BC%88%3A336-337%EF%BC%89%EF%BC%9B%E4%BD%8E%E9%80%9A%E6%BB%A4%E6%B3%A2%EF%BC%88%3A342%EF%BC%89%22%5D%0A%20%20%20%20P%20--%3E%7C%22R_world_base%E1%B5%80%EF%BC%88%3A194-196%EF%BC%89%22%7C%20OUT%5B%22wrench_base%20%E2%86%92%20%E5%AE%9A%E5%BE%8B%E7%9A%84%20F_base%22%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[c(`
          Loading...
        `,-1)])]),_:1})),e[6]||(e[6]=o('<ul><li>工具重量作为向量只有写在 world 里才是常量 <code>[0,0,−mg]</code>（<code>end_effector_weight_[2] = −CoG.force</code>，:126）；在 base 里方向随臂姿态变。</li> <li>力矩项 <code>r×w</code>：质心不在测点上时传感器多读一个重力力偶，<code>r = cog_pos_</code> 参数经 <code>R_world_cog</code> 旋到 world（:189、:337）。</li> <li>命名规律：<code>A_B_</code> = B 在 A 下的位姿；复合时下标相邻相消——<code>R_world_base · R_base_sensor = R_world_sensor</code>（:187 正是这行乘法）。</li></ul> <h2 id="弹簧零点与两个场景" tabindex="-1">弹簧零点与两个场景 <a class="header-anchor" href="#弹簧零点与两个场景" aria-label="Permalink to &quot;弹簧零点与两个场景&quot;">​</a></h2> <p>X = 当前传感器位姿 − 参考传感器位姿（平移相减、旋转取 AngleAxis 对数，:261-265），输出 = 参考 + Δq（:214-223 叠加）。</p> <ul><li>自由空间：F=0，偏移按二阶规律衰减到零，臂跟随上游轨迹——没被碰时必须还在轨道上。</li> <li>接触：稳态 K·X = F，弹簧压缩到与接触力平衡。注入 F_des 后（Humble 版没有这个参数，注入它的完整二次开发过程见<a href="./AdmittanceController 恒力控制二次开发踩坑记.html">本站《AdmittanceController 恒力控制二次开发踩坑记》</a>）稳态变 K·X = F − F_des。</li></ul> <h2 id="源码里的三处冗余-工业控制器视角的判断" tabindex="-1">源码里的三处冗余（工业控制器视角的判断） <a class="header-anchor" href="#源码里的三处冗余-工业控制器视角的判断" aria-label="Permalink to &quot;源码里的三处冗余（工业控制器视角的判断）&quot;">​</a></h2> <ol><li><code>base_tip_</code> 是死计算：全包 grep 只有 hpp:55 声明和 impl:155 写入，零读取，rule 也无 getter 把它递给控制器；<code>git log -S</code> 显示随首个 commit <code>9be3bfe2</code>（2022-10-10，PR #370）进入至今无人消费。每周期为它付一次 FK。</li> <li>每周期 7 次 FK、1 次重复：<code>calculate_admittance_rule</code> :260 重算当前构型传感器位姿，输入与 <code>base_ft_</code> 完全相同（<code>current_joint_pos</code> 是 :199 从 <code>current_joint_state.positions</code> 拷的）。推测是为了让定律函数只依赖 <code>AdmittanceState</code> 自洽，重复计算是事实。</li> <li><code>world_base_</code> 对固定基座机器人（fixed_world_frame 与 base 刚连）物理上是常量，仍每周期重算。按工业控制器的标准，这两处都是可缓存项。</li></ol> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>六个位姿是把力、重力、M/D/K、弹簧零点搬进 base 帧的桥：只有 <code>ref_base_ft_</code> 用参考关节角（弹簧零点需要「上游要你去哪」），其余五个全用当前关节角——力怎么旋转、重力怎么减、参数怎么换系只取决于臂的真实姿态。</li> <li>力的通路绕道 world：重量只有在 world 帧才是常向量 <code>[0,0,−mg]</code>，先旋到 world 减重力再旋回 base；命名规律 <code>A_B_</code> 复合时下标相邻相消。</li> <li>三处冗余（工业控制器视角）：<code>base_tip_</code> 自首个 commit 起零读取、每周期 7 次 FK 含 1 次重复、<code>world_base_</code> 固定基座下物理上是常量——都是可缓存项。</li></ul> <p>控制器的生命周期、参数系统与实测排坑见<a href="./AdmittanceController 源码精读与全流程走查.html">本站《AdmittanceController 源码精读与全流程走查》</a>；力控算法层面导纳与 PI 的定位对比，见<a href="./导纳控制与PI控制.html">本站《导纳控制与 PI 控制：力控算法的定位与对比》</a>。</p>',17))])}const u=s(E,[["render",B]]);export{p as __pageData,u as default};
